declare(strict_types=1);namespace BSPDesign;require dirname(__DIR__).'/_lib/site.php';security();header('Content-Type: application/json; charset=utf-8');header('X-Robots-Tag: noindex');function respond(array $r,int $code=200):never{http_response_code($code);echo enc($r);exit;}$path=parse_url($_SERVER['REQUEST_URI']??'',PHP_URL_PATH);if(!in_array($path,[ROOT.'api/',ROOT.'api/index.php'],true))respond(['error'=>'Not found'],404);$method=$_SERVER['REQUEST_METHOD']??'GET';if(in_array($method,['GET','HEAD'],true))respond(catalog());if($method!=='POST'){header('Allow: GET, HEAD, POST');respond(['error'=>'Method not allowed'],405);}try{if(!preg_match('~^application/json(?:\s*;|$)~i',$_SERVER['CONTENT_TYPE']??''))throw new \InvalidArgumentException('Expected application/json.');$d=decode_text(file_get_contents('php://input',false,null,0,65537));if(($d['action']??'')==='seal'){keys($d,['action','protocol'],'request');respond(['sealed'=>seal(obj($d['protocol']??null,'Protocol'))]);}if(($d['action']??'')==='run'){keys($d,['action','sealed','expected_sha256'],'request');$expected=$d['expected_sha256']??null;if($expected!==null&&(!is_string($expected)||!preg_match('/^[0-9a-f]{64}$/D',$expected)))throw new \InvalidArgumentException('Invalid expected result digest.');$r=run(obj($d['sealed']??null,'Sealed protocol'));respond(['result'=>$r,'replay_match'=>$expected===null?null:hash_equals($expected,$r['result_sha256'])]);}throw new \InvalidArgumentException('Unknown action.');}catch(\InvalidArgumentException|\JsonException $e){respond(['error'=>$e->getMessage()],400);}catch(\Throwable $e){error_log('BSP design: '.$e->getMessage());respond(['error'=>'Calculation failed'],500);}
